PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS repositories (id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES users(id), state TEXT NOT NULL CHECK(state IN ('staging','published')), metadata TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS deleted_publications (repository_id TEXT PRIMARY KEY, deleted_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS repository_members (repository_id TEXT NOT NULL REFERENCES repositories(id), user_id TEXT NOT NULL, role TEXT NOT NULL, PRIMARY KEY(repository_id,user_id));
CREATE TABLE IF NOT EXISTS manifests (hash TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS manifest_entries (manifest_hash TEXT NOT NULL REFERENCES manifests(hash), path TEXT NOT NULL, sha256 TEXT NOT NULL, source TEXT, object_hash TEXT, size INTEGER NOT NULL, PRIMARY KEY(manifest_hash,path));
CREATE TABLE IF NOT EXISTS snapshots (id TEXT PRIMARY KEY, manifest_hash TEXT NOT NULL REFERENCES manifests(hash), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS commits (id TEXT PRIMARY KEY, repository_id TEXT NOT NULL REFERENCES repositories(id), snapshot_id TEXT NOT NULL REFERENCES snapshots(id), author TEXT NOT NULL, created_at TEXT NOT NULL, data TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS commits_repository ON commits(repository_id,created_at);
CREATE TABLE IF NOT EXISTS branches (repository_id TEXT NOT NULL REFERENCES repositories(id), name TEXT NOT NULL, head TEXT NOT NULL REFERENCES commits(id), owner TEXT NOT NULL, protected INTEGER NOT NULL, base_commit TEXT, PRIMARY KEY(repository_id,name));
CREATE TABLE IF NOT EXISTS objects (hash TEXT PRIMARY KEY, size INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS object_references (repository_id TEXT NOT NULL REFERENCES repositories(id), owner_id TEXT NOT NULL, object_hash TEXT NOT NULL REFERENCES objects(hash), PRIMARY KEY(repository_id,owner_id,object_hash));
CREATE INDEX IF NOT EXISTS references_object ON object_references(object_hash);
CREATE TABLE IF NOT EXISTS uploads (ticket_hash TEXT PRIMARY KEY, repository_id TEXT NOT NULL REFERENCES repositories(id), user_id TEXT NOT NULL, object_hash TEXT NOT NULL, size INTEGER NOT NULL, expires_at INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS invitations (token_hash TEXT PRIMARY KEY, repository_id TEXT NOT NULL REFERENCES repositories(id), role TEXT NOT NULL, recipient TEXT, expires_at INTEGER NOT NULL, uses INTEGER NOT NULL DEFAULT 0, max_uses INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS pull_requests (repository_id TEXT NOT NULL REFERENCES repositories(id), id TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(repository_id,id));
CREATE TABLE IF NOT EXISTS pull_request_comments (repository_id TEXT NOT NULL, pr_id TEXT NOT NULL, ordinal INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY(repository_id,pr_id,ordinal));
CREATE TABLE IF NOT EXISTS tags (repository_id TEXT NOT NULL REFERENCES repositories(id), name TEXT NOT NULL, commit_id TEXT NOT NULL REFERENCES commits(id), PRIMARY KEY(repository_id,name));
CREATE TABLE IF NOT EXISTS releases (repository_id TEXT NOT NULL, tag TEXT NOT NULL, data TEXT NOT NULL, PRIMARY KEY(repository_id,tag));
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, repository_id TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, at INTEGER NOT NULL);

CREATE INDEX IF NOT EXISTS commits_snapshot ON commits(snapshot_id);
CREATE INDEX IF NOT EXISTS snapshots_manifest ON snapshots(manifest_hash);
CREATE INDEX IF NOT EXISTS uploads_repository ON uploads(repository_id);
CREATE INDEX IF NOT EXISTS uploads_object ON uploads(object_hash, expires_at);
CREATE INDEX IF NOT EXISTS invitations_repository ON invitations(repository_id);
CREATE INDEX IF NOT EXISTS events_repository ON events(repository_id);
